<script setup>
import { computed, ref, watch } from 'vue'
import { getFarmManagementStats } from '@/api/adminPhase2'
import { formatDateTime } from '@/utils/dataAdapters'
const props=defineProps({farmIds:{type:Array,default:()=>[]}});const rows=ref([]);const plotId=ref('');watch(()=>props.farmIds.join('|'),async()=>{const results=await Promise.all(props.farmIds.map(getFarmManagementStats));rows.value=results.flat()},{immediate:true});const filtered=computed(()=>rows.value.filter(x=>!plotId.value||x.plotId===plotId.value))
</script>
<template><el-card class="management-stats"><template #header><div class="stats-head"><div><strong>地块管理与任务完成情况</strong><p>负责人、品种、阶段、提醒、任务完成率和最近灌溉。</p></div><el-select v-model="plotId" clearable placeholder="全部地块"><el-option v-for="item in rows" :key="item.plotId" :label="item.plotName" :value="item.plotId"/></el-select></div></template><el-table :data="filtered"><el-table-column prop="plotName" label="地块"/><el-table-column prop="farmerName" label="负责人"/><el-table-column prop="variety" label="品种"/><el-table-column label="当前阶段"><template #default="s">{{s.row.currentStage?.stageName||'未配置'}}</template></el-table-column><el-table-column prop="soilMoisture" label="湿度（%）"/><el-table-column prop="pendingAlerts" label="待处理提醒"/><el-table-column label="任务完成率"><template #default="s"><el-progress :percentage="s.row.taskCompletionRate"/></template></el-table-column><el-table-column label="最近灌溉" min-width="165"><template #default="s">{{formatDateTime(s.row.lastIrrigationAt,'暂无')}}</template></el-table-column></el-table></el-card></template>
<style scoped>.management-stats{margin-bottom:20px;border-radius:16px}.stats-head{display:flex;justify-content:space-between;align-items:center}.stats-head p{margin:5px 0 0;color:#81918b;font-size:12px}.stats-head .el-select{width:180px}</style>
